SELECT * FROM public.initialize_work_order(pg_temp.k(33),pg_temp.k(11),pg_temp.k(21),0,pg_temp.k(143));
SELECT lives_ok($$SELECT * FROM public.begin_field_photo_upload(pg_temp.k(21),pg_temp.k(51),pg_temp.payload())$$,'legacy project capture remains available');
