SELECT lives_ok($$SELECT * FROM public.save_work_order_plan(pg_temp.k(31),pg_temp.k(11),pg_temp.k(21),1,pg_temp.plan(),'Synthetic later instruction',pg_temp.k(144))$$,'later instructions do not rewrite capture provenance');
SELECT lives_ok($$SELECT * FROM public.begin_field_photo_upload(pg_temp.k(21),pg_temp.k(52),pg_temp.capture_payload(31,(SELECT id FROM public.work_order_plan_versions WHERE action_id=pg_temp.k(31) AND version=1)))$$,'lost intent response returns the same original captured plan');
SELECT throws_ok($$SELECT * FROM public.begin_field_photo_upload(pg_temp.k(21),pg_temp.k(52),pg_temp.capture_payload(31,(SELECT id FROM public.work_order_plan_versions WHERE action_id=pg_temp.k(31) AND version=2)))$$,'22023',NULL,'same capture cannot be retargeted to new instructions');
SELECT throws_ok($$SELECT * FROM public.begin_field_photo_upload(pg_temp.k(21),pg_temp.k(55),pg_temp.capture_payload(32,(SELECT id FROM public.work_order_plan_versions WHERE action_id=pg_temp.k(31) AND version=1)))$$,'22023',NULL,'another task plan is rejected');
SELECT throws_ok($$SELECT * FROM public.begin_field_photo_upload(pg_temp.k(22),pg_temp.k(55),pg_temp.capture_payload())$$,'42501',NULL,'another project cannot reuse task context');
SELECT throws_ok($$SELECT * FROM public.begin_field_photo_upload(pg_temp.k(21),pg_temp.k(55),pg_temp.payload()||'{"workOrder":null}')$$,'22023',NULL,'explicit null is not a project capture fallback');
SELECT throws_ok($$SELECT * FROM public.begin_field_photo_upload(pg_temp.k(21),pg_temp.k(55),pg_temp.capture_payload()||jsonb_build_object('workOrder',(pg_temp.capture_payload()->'workOrder')||'{"invented":true}'))$$,'22023',NULL,'unknown capture fields are rejected');
SELECT lives_ok($$SELECT * FROM public.begin_field_photo_upload(pg_temp.k(21),pg_temp.k(53),pg_temp.capture_payload(33))$$,'initialized task without instructions can retain its original fact');
