SELECT throws_ok($$SELECT * FROM public.begin_field_photo_upload(pg_temp.k(21),pg_temp.k(56),pg_temp.capture_payload(33))$$,'PT410',NULL,'new capture after cancellation is refused');
SELECT lives_ok($$SELECT * FROM public.begin_field_photo_upload(pg_temp.k(21),pg_temp.k(53),pg_temp.capture_payload(33))$$,'exact accepted capture may resume after cancellation with current access');
