SELECT lives_ok($$SELECT public.get_work_order_captured_photo_original(pg_temp.k(52),pg_temp.k(31),pg_temp.k(11),pg_temp.k(21))$$,'external assignee can authorize exact task original');
SELECT throws_ok($$SELECT public.get_work_order_captured_photo_original(pg_temp.k(54),pg_temp.k(31),pg_temp.k(11),pg_temp.k(21))$$,'42501',NULL,'capture from another task is not exposed through same scope');
